43	/****************************************************************************
44	 * EIOINTC (Extended I/O Interrupt Controller)
45	 ****************************************************************************/
46	
47	#define EIOINTC_VEC_COUNT          128
48	#define EIOINTC_NODEMAP_COUNT      (EIOINTC_VEC_COUNT / 32)
49	#define EIOINTC_IPMAP_COUNT        (EIOINTC_VEC_COUNT / 128)
50	#define EIOINTC_ROUTE_COUNT        (EIOINTC_VEC_COUNT / 4)
51	#define EIOINTC_BOUNCE_COUNT       (EIOINTC_VEC_COUNT / 32)
52	#define EIOINTC_ENABLE_COUNT       (EIOINTC_VEC_COUNT / 32)
53	#define EIOINTC_ISR_COUNT          (EIOINTC_VEC_COUNT / 64)
54	
55	#define EIOINTC_ENABLE_VEC(vector) \
56	  (EIOINTC_REG_ENABLE + ((vector >> 5) << 2))
57	
58	static void eiointc_init(void)
59	{
60	  uint32_t data;
61	  int i;
62	
63	  uint64_t misc = iocsr_read64(LOONGARCH_IOCSR_MISC_FUNC);
64	  misc |= IOCSR_MISC_FUNC_EXT_IOI_EN;
65	  iocsr_write64(misc, LOONGARCH_IOCSR_MISC_FUNC);
66	
67	  for (i = 0; i < EIOINTC_NODEMAP_COUNT; i++)
68	    {
69	      data = (((1 << (i * 2 + 1)) << 16) | (1 << (i * 2)));
70	      iocsr_write32(data, EIOINTC_REG_NODEMAP + i * 4);
71	    }
72	
73	  for (i = 0; i < EIOINTC_IPMAP_COUNT; i++)
74	    {
75	      data = (1U << 1) | ((1U << 1) << 8) |
76	             ((1U << 1) << 16) | ((1U << 1) << 24);
77	      iocsr_write32(data, EIOINTC_REG_IPMAP + i * 4);
78	    }
79	
80	  for (i = 0; i < EIOINTC_ROUTE_COUNT; i++)
81	    {
82	      data = 0x1 | (0x1 << 8) | (0x1 << 16) | (0x1 << 24);
83	      iocsr_write32(data, EIOINTC_REG_ROUTE + i * 4);
84	    }
85	
86	  for (i = 0; i < EIOINTC_BOUNCE_COUNT; i++)
87	    {
88	      iocsr_write32(0xffffffff, EIOINTC_REG_BOUNCE + i * 4);
89	      iocsr_write32(0x0, EIOINTC_REG_ENABLE + i * 4);
90	    }
91	}
92	
93	static int eiointc_dispatch(int irq, void *context, void *arg)
94	{
95	  uint64_t pending;
96	  int i;
97	
98	  for (i = 0; i < EIOINTC_ISR_COUNT; i++)
99	    {
100	      pending = iocsr_read64(EIOINTC_REG_ISR + (i << 3));
101	      if (!pending)
102	        {
103	          continue;
104	        }
105	
106	      iocsr_write64(pending, EIOINTC_REG_ISR + (i << 3));
107	
108	      while (pending)
109	        {
110	          int bit = __builtin_ffsl(pending) - 1;
111	          int vector = bit + 64 * i;
112	          int ext_irq = LS2K300_IRQ_EIOINTC_START + vector;
113	
114	          irq_dispatch(ext_irq, (uintreg_t *)context);
115	          pending &= ~((uint64_t)1 << bit);
116	        }
117	    }
118	
119	  return OK;
120	}
