122	/****************************************************************************
123	 * ICU (Traditional I/O Interrupt Controller)
124	 * Reference: linux-5.10/drivers/irqchip/irq-loongson-2k500-iointc.c
125	 * DTS: icu@0x16001400, cascades to CPU IP2 (interrupt 4)
126	 ****************************************************************************/
127	
128	#define ICU_IRQ_COUNT             64
129	
130	#define ICU_INTISR_REG(base, i)   ((base) + 0x20 + (((i) > 31) ? 0x40 : 0))
131	#define ICU_INTEN_REG(base, i)    ((base) + 0x24 + (((i) > 31) ? 0x40 : 0))
132	#define ICU_INTENSET_REG(base, i) ((base) + 0x28 + (((i) > 31) ? 0x40 : 0))
133	#define ICU_INTENCLR_REG(base, i) ((base) + 0x2c + (((i) > 31) ? 0x40 : 0))
134	#define ICU_INTPOL_REG(base, i)   ((base) + 0x30 + (((i) > 31) ? 0x40 : 0))
135	#define ICU_INTEDGE_REG(base, i)  ((base) + 0x34 + (((i) > 31) ? 0x40 : 0))
136	#define ICU_INTAUTO_REG(base, i)  ((base) + 0x3c + (((i) > 31) ? 0x40 : 0))
137	#define ICU_IRQ_ROUTE_REG(base, i) ((base) + 0x00 + (((i) > 31) ? 0x40 : 0) + ((i) % 32))
138	#define ICU_COREISR_REG(isr, i)   ((isr) + (i) * 8)
139	
140	static void icu_init(void)
141	{
142	  uintptr_t base = LS2K300_ICU_REG_BASE;
143	  int i;
144	
145	  for (i = 0; i < ICU_IRQ_COUNT; i++)
146	    {
147	      putreg8(0x41, ICU_IRQ_ROUTE_REG(base, i));
148	    }
149	
150	  putreg32(0x0, ICU_INTEN_REG(base, 0));
151	  putreg32(0x0, ICU_INTEN_REG(base, 32));
152	  putreg32(0x0, ICU_INTPOL_REG(base, 0));
153	  putreg32(0x0, ICU_INTPOL_REG(base, 32));
154	  putreg32(0x0, ICU_INTEDGE_REG(base, 0));
155	  putreg32(0x0, ICU_INTEDGE_REG(base, 32));
156	  putreg32(0x0, ICU_INTAUTO_REG(base, 0));
157	  putreg32(0x0, ICU_INTAUTO_REG(base, 32));
158	}
159	
160	static int icu_dispatch(int irq, void *context, void *arg)
161	{
162	  uintptr_t base = LS2K300_ICU_REG_BASE;
163	  uintptr_t isr_base = LS2K300_ICU_ISR_BASE;
164	  uint64_t pending;
165	  uint32_t reg_val;
166	  uint32_t inten_lo;
167	  uint32_t inten_hi;
168	
169	  pending = getreg32(ICU_COREISR_REG(isr_base, 0));
170	  reg_val = getreg32(ICU_COREISR_REG(isr_base, 1));
171	  pending |= (uint64_t)reg_val << 32;
172	
173	  if (!pending)
174	    {
175	      return OK;
176	    }
177	
178	  inten_lo = getreg32(ICU_INTEN_REG(base, 0));
179	  inten_hi = getreg32(ICU_INTEN_REG(base, 32));
180	
181	  while (pending)
182	    {
183	      int bit = __builtin_ffsl(pending) - 1;
184	      int icu_irq = LS2K300_IRQ_ICU_START + bit;
185	      uint32_t inten_reg = (bit < 32) ? inten_lo : inten_hi;
186	      uint32_t bit_mask = 1 << (bit % 32);
187	
188	      putreg32(bit_mask, ICU_INTENCLR_REG(base, bit));
189	
190	      irq_dispatch(icu_irq, (uintreg_t *)context);
191	
192	      if (inten_reg & bit_mask)
193	        {
194	          putreg32(bit_mask, ICU_INTENSET_REG(base, bit));
195	        }
196	
197	      pending &= ~((uint64_t)1 << bit);
198	    }
199	
200	  return OK;
201	}
