207	void up_irqinitialize(void)
208	{
209	  up_irq_save();
210	
211	  loongarch_exception_attach();
212	
213	  write_csr_ecfg(ECFGF(ECFGB_TIMER) | ECFGF(ECFGB_IP1) |
214	                 ECFGF(ECFGB_IP2));
215	
216	  eiointc_init();
217	  icu_init();
218	
219	  irq_attach(LOONGARCH_IRQ_IP1, eiointc_dispatch, NULL);
220	  irq_attach(LOONGARCH_IRQ_IP2, icu_dispatch, NULL);
221	
222	#if defined(CONFIG_STACK_COLORATION) && CONFIG_ARCH_INTERRUPTSTACK > 15
223	  size_t intstack_size = (CONFIG_ARCH_INTERRUPTSTACK & ~15);
224	  loongarch_stack_color(g_intstackalloc, intstack_size);
225	#endif
226	
227	#ifndef CONFIG_SUPPRESS_INTERRUPTS
228	  loongarch_color_intstack();
229	  up_irq_enable();
230	#endif
231	}
