233	void up_disable_irq(int irq)
234	{
235	  unsigned long ecfg;
236	
237	  if (irq == LOONGARCH_IRQ_TIMER)
238	    {
239	      ecfg = csr_readq(LOONGARCH_CSR_ECFG);
240	      ecfg &= ~ECFGF(ECFGB_TIMER);
241	      csr_writeq(ecfg, LOONGARCH_CSR_ECFG);
242	    }
243	  else if (irq >= LS2K300_IRQ_ICU_START &&
244	           irq < LS2K300_IRQ_ICU_START + LS2K300_IRQ_ICU_COUNT)
245	    {
246	      int hwirq = irq - LS2K300_IRQ_ICU_START;
247	      uintptr_t base = LS2K300_ICU_REG_BASE;
248	      putreg32(1 << (hwirq % 32), ICU_INTENCLR_REG(base, hwirq));
249	    }
250	  else if (irq >= LS2K300_IRQ_EIOINTC_START &&
251	           irq < LS2K300_IRQ_EIOINTC_START + LS2K300_IRQ_EIOINTC_COUNT)
252	    {
253	      int vector = irq - LS2K300_IRQ_EIOINTC_START;
254	      uint32_t reg = EIOINTC_ENABLE_VEC(vector);
255	      uint32_t data = iocsr_read32(reg);
256	      data &= ~(1U << (vector & 0x1f));
257	      iocsr_write32(data, reg);
258	    }
259	}
