261	void up_enable_irq(int irq)
262	{
263	  unsigned long ecfg;
264	
265	  if (irq == LOONGARCH_IRQ_TIMER)
266	    {
267	      ecfg = csr_readq(LOONGARCH_CSR_ECFG);
268	      ecfg |= ECFGF(ECFGB_TIMER);
269	      csr_writeq(ecfg, LOONGARCH_CSR_ECFG);
270	    }
271	  else if (irq >= LS2K300_IRQ_ICU_START &&
272	           irq < LS2K300_IRQ_ICU_START + LS2K300_IRQ_ICU_COUNT)
273	    {
274	      int hwirq = irq - LS2K300_IRQ_ICU_START;
275	      uintptr_t base = LS2K300_ICU_REG_BASE;
276	      putreg32(1 << (hwirq % 32), ICU_INTENSET_REG(base, hwirq));
277	    }
278	  else if (irq >= LS2K300_IRQ_EIOINTC_START &&
279	           irq < LS2K300_IRQ_EIOINTC_START + LS2K300_IRQ_EIOINTC_COUNT)
280	    {
281	      int vector = irq - LS2K300_IRQ_EIOINTC_START;
282	      uint32_t reg = EIOINTC_ENABLE_VEC(vector);
283	      uint32_t data = iocsr_read32(reg);
284	      data |= (1U << (vector & 0x1f));
285	      iocsr_write32(data, reg);
286	    }
287	}
